'use strict';
// Migration evidence is generated by the actual frozen 009b4aa Store. No real
// chats, user databases, model calls or desktop integration are involved.
const test=require('node:test'),assert=require('node:assert/strict');
const fs=require('node:fs'),os=require('node:os'),path=require('node:path');
const {DatabaseSync}=require('node:sqlite');
const {Store}=require('../src/store.cjs');
const {scope,complete,tableRows,snapshot,buildLegacyDatabase,FROZEN_REVISION}=require('./fixtures/evidence-backed-memory.cjs');
function database(t){
 const dir=fs.mkdtempSync(path.join(os.tmpdir(),'qq-evidence-legacy-')),filename=path.join(dir,'fictional.sqlite');
 t.after(()=>fs.rmSync(dir,{recursive:true,force:true}));
 const fixture=buildLegacyDatabase(filename);assert.equal(fixture.frozenRevision,FROZEN_REVISION);
 return {filename,...fixture};
}
function durable(db){
 const tables=db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name").all().map(row=>row.name);
 return Object.fromEntries(tables.map(name=>[name,tableRows(db,name)]));
}

test('opening a real frozen old Store preserves string QQ IDs, source revisions, notes and withdrawn corrections',t=>{
 const fixture=database(t),store=new Store(fixture.filename);t.after(()=>store.close());
 const after=snapshot(store),before=fixture.before;
 assert.deepEqual(after.messages,before.messages);
 assert.ok(after.messages.every(message=>typeof message.messageId==='string'));
 assert.equal(after.messages.find(message=>message.messageId===fixture.ids.recalledId).recalled,true);
 // Speaker-fingerprinted revision cutover (design 6.1 phase 4, D1): the
 // upgrade deliberately re-hashes every source revision so a sender-role
 // correction invalidates derived memory. Bodies, ids, times and disclosure
 // must survive unchanged; revisions must be remapped CONSISTENTLY (each
 // stored revision equals the fingerprinted hash of that source content, and
 // every live revision pointer - journal, dependencies, records, notes -
 // moved together), never left half-migrated.
 const stripRevision=source=>{const{revision,evidenceRevisions,...rest}=source;return rest;};
 assert.deepEqual(after.sources.map(stripRevision),before.sources.map(stripRevision),'structural migration must not rewrite original bodies');
 assert.ok(after.sources.every(source=>source.revision!==before.sources.find(item=>item.id===source.id)?.revision),'every revision is re-hashed by the fingerprint cutover');
 const upgradedLive=new Map(store.memorySources(scope).map(source=>[source.id,source.revision]));
 assert.ok(after.sources.every(source=>upgradedLive.get(source.id)===source.revision),'stored revisions match the live fingerprinted projection');
 for(const source of after.sources)for(const [id,revision] of Object.entries(source.evidenceRevisions||{}))assert.equal(upgradedLive.get(id),revision,'embedded note lineage revisions are remapped to the live hash');
 const stripNoteRevisions=note=>{const{evidenceRevisions,...rest}=note;return rest;};
 assert.deepEqual(after.companion.notes.map(stripNoteRevisions),before.companion.notes.map(stripNoteRevisions));
 for(const note of after.companion.notes)for(const [id,revision] of Object.entries(note.evidenceRevisions||{}))assert.equal(upgradedLive.get(id),revision,'note evidence revisions are remapped to the live hash');
 assert.deepEqual(after.companion.goal,before.companion.goal);
 assert.equal(after.sources.some(source=>source.id==='qq:'+fixture.ids.forgottenId),false);
 assert.equal(after.sources.find(source=>source.id==='private:legacy-corrected-source').text,'A fictional source after correction.');
 const oldById=new Map(before.view.claims.map(row=>[row.id,row]));
 for(const row of after.view.claims){const old=oldById.get(row.id);if(old){assert.equal(row.lifecycle,old.lifecycle);assert.ok(row.version>=old.version);for(const [id,revision] of Object.entries(row.sourceRevisions||{}))assert.equal(upgradedLive.get(id),revision,'view evidence revisions follow the fingerprinted cutover');}}
 for(const id of [fixture.ids.oldClaimId,fixture.ids.interestId])assert.equal(after.view.claims.find(row=>row.id===id)?.lifecycle,'withdrawn');
 assert.equal(after.view.claims.find(row=>row.id===fixture.ids.correctedClaimId)?.lifecycle,'active');
 for(const row of before.records)assert.ok(after.records.some(current=>current.id===row.id),'retain useful old summaries for historical navigation');
 assert.ok(after.schemaVersion>=before.schemaVersion);
 assert.ok(after.status.version>=before.status.version);
 assert.equal(store.db.prepare('PRAGMA integrity_check').get().integrity_check,'ok');
});

test('legacy derived knowledge stays historical until original semantic reverification without invented fields',t=>{
 const fixture=database(t),store=new Store(fixture.filename);t.after(()=>store.close());
 const liveRevisions=new Map(store.memorySources(scope).map(source=>[source.id,source.revision]));
 const receipt=store.ensureKnowledgeMigration(scope);assert.ok(receipt);
 const oldRows=new Map(fixture.before.records.map(row=>[row.id,JSON.parse(row.record)]));
 const after=tableRows(store.db,'memory_records').map(row=>JSON.parse(row.record));
 for(const [id,old] of oldRows){
  const current=after.find(row=>row.id===id);assert.ok(current,'keep the historical old record');
  assert.equal(current.semanticReview?.status,'legacy_unreviewed');assert.equal(current.reviewComplete,false);
  assert.equal(current.text,old.text);
   // Structural reason (D1 fingerprint cutover): record evidence pointers are
   // remapped to the new hashes instead of staying byte-equal to the baseline;
   // the assertion is consistency with the live projection, not stasis.
   assert.deepEqual(Object.keys(current.sourceRevisions||{}),Object.keys(old.sourceRevisions||{}));
   for(const [id,revision] of Object.entries(current.sourceRevisions||{}))assert.equal(liveRevisions.get(id),revision,'record evidence revisions follow the fingerprinted cutover');
  for(const field of ['condition','validFrom','validUntil','occurredAt'])if(old[field]===undefined)assert.ok(current[field]===undefined||current[field]===null,`do not invent ${field} from an old summary`);
 }
 const person=store.personUnderstanding(scope);
 for(const subject of ['self','contact','dyad']){
  for(const row of [...person[subject].knownFacts,...person[subject].recentCircumstances,...person[subject].boundaries])assert.equal(oldRows.has(row.id),false,'old structural migration is not semantic reverification');
 }
 const before=durable(store.db),again=store.ensureKnowledgeMigration(scope);assert.ok(again);
 assert.deepEqual(durable(store.db),before,'repeat migration cannot upgrade old certainty, versions or coverage');
});

test('reopening an upgraded old Store is idempotent and never resets unfinished evidence coverage',t=>{
 const fixture=database(t);let store=new Store(fixture.filename);
 try{
  store.memorySources(scope);store.relationshipView(scope);
  const before=durable(store.db),journal=tableRows(store.db,'memory_journal'),schema=store.db.prepare('PRAGMA user_version').get().user_version;
  assert.ok(journal.some(row=>row.source_id===fixture.ids.longSourceId&&row.cursor>0&&row.status==='pending'));
  store.close();store=new Store(fixture.filename);store.memorySources(scope);store.relationshipView(scope);
  assert.deepEqual(durable(store.db),before,'opening again cannot invent semantic review or another migration');
  assert.equal(store.db.prepare('PRAGMA user_version').get().user_version,schema);
  assert.equal(store.memorySources(scope).some(source=>source.id==='qq:'+fixture.ids.forgottenId),false);
  const recalled=fixture.before.messages.find(message=>message.messageId===fixture.ids.recalledId);
  store.add(scope,[{...recalled,recalled:false,text:'A stale un-recalled import.'}]);
  assert.equal(store.memorySources(scope).some(source=>source.id==='qq:'+fixture.ids.recalledId),false,'later native import cannot resurrect an observed recall');
 }finally{store.close();}
});

test('a failure after opening an old Store rolls back derived writes, receipts and review cursor together',t=>{
 const fixture=database(t),store=new Store(fixture.filename);t.after(()=>store.close());
 const batch=store.memoryBatch(scope,{maxBytes:4000}),before=durable(store.db);
 assert.ok(batch.sources.some(source=>source.id===fixture.ids.longSourceId));
 store.db.exec("CREATE TRIGGER fictional_review_interruption BEFORE UPDATE ON memory_journal WHEN OLD.status='pending' BEGIN SELECT RAISE(ABORT,'fictional review interruption'); END");
 const failed=store.applyMemoryBatch(scope,batch,complete(batch,{episodes:[{text:'A summary that must not survive the failed transaction.',sourceIds:[fixture.ids.longSourceId]}]}));
 assert.equal(failed.applied,false);assert.match(failed.detail||'',/fictional review interruption/);
 assert.deepEqual(durable(store.db),before,'a rejected review cannot leave a derived row or consume a source segment');
 store.db.exec('DROP TRIGGER fictional_review_interruption');
 assert.equal(store.applyMemoryBatch(scope,batch,complete(batch)).applied,true,'the exact unchanged batch remains resumable');
 assert.equal(store.applyMemoryBatch(scope,batch,complete(batch)).applied,false,'a receipt cannot be replayed as a second review');
});

test('failed structural migration keeps a fictional database intact and rejects future schema versions without writes',t=>{
 const fixture=database(t),db=new DatabaseSync(fixture.filename),before=durable(db),version=db.prepare('PRAGMA user_version').get().user_version;
 db.exec("CREATE TRIGGER fictional_schema_interruption BEFORE INSERT ON schema_migrations WHEN NEW.version>1 BEGIN SELECT RAISE(ABORT,'fictional schema interruption'); END");db.close();
 // The candidate may add a structural migration or retain the existing schema;
 // if it migrates, interruption must undo every preceding schema/data write.
 let opened;
 try{opened=new Store(fixture.filename);}catch(error){
  assert.match(error.message,/fictional schema interruption/);
  const check=new DatabaseSync(fixture.filename);assert.deepEqual(durable(check),before);assert.equal(check.prepare('PRAGMA user_version').get().user_version,version);check.close();
 }finally{opened?.close();}
 const future=path.join(path.dirname(fixture.filename),'future.sqlite'),newer=new DatabaseSync(future);newer.exec('PRAGMA user_version=99');newer.close();
 assert.throws(()=>new Store(future),/newer|unsupported/i);
 const check=new DatabaseSync(future);assert.equal(check.prepare("SELECT count(*) n FROM sqlite_master WHERE type='table'").get().n,0);assert.equal(check.prepare('PRAGMA user_version').get().user_version,99);check.close();
});
